#!/usr/bin/env python3
"""layered_gate.py 鈥?mechanical gate guards for cold_start 鈫?layered flips.

Implements the "no passthrough flip without a consumer" rejection gate as
code (``phase2_architecture_design.md`` 搂2.1 integration note + migration
strategy): the central trap of the shipped system 鈥?flipping routing open
while ``send_l2`` had no consumer 鈥?becomes *unrepresentable*. Setting
``routing.mode = "layered"`` is only legal through :meth:`LayeredGate.enable`,
which checks **all six conditions** and refuses on any failure:

1. **consumer heartbeat** 鈥?``data/l2_queue/consumer_heartbeat.json`` exists
   and is fresher than ``consumer_heartbeat_max_age_s``;
2. **exactly-once canary** 鈥?:meth:`l2_consumer.L2Consumer.run_canary` passes
   live (3 sends 鈫?3 dispatches; crash-after-claim reaped and re-dispatched
   exactly once; settle drain adds zero);
3. **K3 verifier model pinned** 鈥?policy ``[models].k3_model`` is a non-empty
   explicit pin (config-sourced, never a hardcoded default);
4. **short-result validator enabled** 鈥?policy ``[validator].enabled`` is
   true and the validator module imports;
5. **state-machine schema compatible** 鈥?the declared v2 transition manifest
   exists and carries every required transition (t27鈥搕38) with
   ``SOL_ADJUDICATE`` absent from the terminal set;
6. **rollback key available** 鈥?policy ``[routing].rollback_mode`` names a
   valid mode (``cold_start``) so a one-key rollback always exists.

Every check result 鈥?pass and fail 鈥?is appended to
``data/governor/layered_gate.ndjsonl`` (V10 doctrine: a gate without a proof
of firing is prose).
"""

from __future__ import annotations

import json
import hashlib
import logging
import os
import sys
import time
import tomllib
from dataclasses import dataclass, field as _dc_field
from pathlib import Path
from typing import Any, Callable, Final, Mapping, Sequence

sys.path.insert(0, str(Path(__file__).resolve().parent))
from l2_consumer import L2Consumer, load_policy  # noqa: E402
from orchestration_common import atomic_write_json, policy_sha256  # noqa: E402
from routing_mode import set_mode  # noqa: E402

__all__ = [
    "ConditionResult",
    "GateResult",
    "LayeredGate",
]

LOG = logging.getLogger("layered_gate")

_REQUIRED_TRANSITIONS_DEFAULT: Final[tuple[str, ...]] = (
    "t27", "t28", "t29", "t30", "t31", "t32",
    "t33", "t34", "t35", "t36", "t37", "t38")


@dataclass(frozen=True)
class ConditionResult:
    """Outcome of one gate condition."""

    name: str
    ok: bool
    detail: str

    def to_dict(self) -> dict[str, Any]:
        """JSON form."""
        return {"name": self.name, "ok": self.ok, "detail": self.detail}


@dataclass(frozen=True)
class GateResult:
    """Structured outcome of the full gate check.

    ``allow`` is ``True`` only when **every** condition passed; ``failed``
    lists the names of failing conditions for actionable remediation.
    """

    allow: bool
    conditions: tuple[ConditionResult, ...]
    failed: tuple[str, ...] = _dc_field(default_factory=tuple)

    def to_dict(self) -> dict[str, Any]:
        """JSON form."""
        return {"allow": self.allow,
                "conditions": [c.to_dict() for c in self.conditions],
                "failed": list(self.failed)}


class LayeredGate:
    """The six-condition mechanical gate for enabling layered routing.

    Args:
        root: LOOP root directory.
        policy: parsed ``orchestration_policy_v2.toml``; loaded fail-closed
            when ``None``.
        canary_runner: injectable canary function (tests); defaults to the
            real :meth:`L2Consumer.run_canary`.
    """

    def __init__(self, root: Path | str,
                 policy: Mapping[str, Any] | None = None,
                 canary_runner: Callable[[], Any] | None = None,
                 clock: Callable[[], float] = time.time) -> None:
        self.root = Path(root).resolve()
        self.policy = (policy if policy is not None else
                       load_policy(self.root / "config" /
                                   "orchestration_policy_v2.toml"))
        self._canary = canary_runner or (
            lambda: L2Consumer.run_canary(dict(self.policy)))
        self._clock = clock
        guard = self.policy.get("gate_guard", {})
        self.log_path = self.root / Path(str(
            guard.get("log", "data/governor/layered_gate.ndjsonl")))
        self.required_transitions: tuple[str, ...] = tuple(
            guard.get("statemachine_required_transitions",
                      _REQUIRED_TRANSITIONS_DEFAULT))
        self.schema_file = self.root / Path(str(
            guard.get("statemachine_schema_file",
                      "config/statemachine_v2_transitions.json")))
        self.canary_marker = (self.root / "data" / "l2_queue" /
                              "exactly_once_canary.json")
        self.validator_marker = (self.root / "data" / "validators" /
                                 "short_result_validator.json")

    # -- individual conditions -------------------------------------------------

    def check_consumer_heartbeat(self) -> ConditionResult:
        """Condition 1: L2 consumer heartbeat exists and is fresh."""
        q = self.policy.get("l2_queue", {})
        max_age = float(q.get("consumer_heartbeat_max_age_s", 300))
        hb_path = (self.root / Path(str(q.get("dir", "data/l2_queue")))
                   / "consumer_heartbeat.json")
        try:
            hb = json.loads(hb_path.read_text(encoding="utf-8"))
            age = self._clock() - float(hb["ts"])
        except (OSError, ValueError, KeyError, TypeError) as exc:
            return ConditionResult(
                "consumer_heartbeat", False,
                "heartbeat unreadable (%s) 鈥?run l2_consumer drain first" % exc)
        if age > max_age:
            return ConditionResult(
                "consumer_heartbeat", False,
                "heartbeat stale: %.0fs > %.0fs" % (age, max_age))
        return ConditionResult("consumer_heartbeat", True,
                               "fresh (%.0fs old)" % age)

    def check_exactly_once_canary(self) -> ConditionResult:
        """Condition 2: the live exactly-once canary passes."""
        try:
            result = self._canary()
        except Exception as exc:
            return ConditionResult("exactly_once_canary", False,
                                   "canary raised: %s" % exc)
        ok = bool(getattr(result, "ok", False))
        detail = str(getattr(result, "detail", result))
        if ok:
            atomic_write_json(self.canary_marker, {
                "schema": "codex-loop-layered-guard/v2",
                "status": "PASS", "ts": self._clock(), "detail": detail,
            })
        return ConditionResult("exactly_once_canary", ok, detail)

    def check_k3_model_pinned(self) -> ConditionResult:
        """Condition 3: verifier model is an explicit config pin."""
        model = str(self.policy.get("models", {}).get("k3_model", "")).strip()
        if not model:
            return ConditionResult(
                "k3_model_pinned", False,
                "policy [models].k3_model is empty 鈥?pin the verifier model "
                "in config (never hardcode)")
        return ConditionResult("k3_model_pinned", True, "pinned: %s" % model)

    def check_validator_enabled(self) -> ConditionResult:
        """Condition 4: short-result validator enabled and importable."""
        if not bool(self.policy.get("validator", {}).get("enabled", False)):
            return ConditionResult("validator_enabled", False,
                                   "policy [validator].enabled is false")
        try:
            import short_result_validator  # noqa: F401, PLC0415
        except ImportError as exc:
            return ConditionResult("validator_enabled", False,
                                   "validator module missing: %s" % exc)
        atomic_write_json(self.validator_marker, {
            "schema": "codex-loop-layered-guard/v2",
            "enabled": True, "ts": self._clock(),
            "validator": "short_result_validator",
        })
        return ConditionResult("validator_enabled", True, "enabled + importable")

    def check_statemachine_schema(self) -> ConditionResult:
        """Condition 5: v2 transition manifest is present and complete."""
        try:
            manifest = json.loads(self.schema_file.read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            return ConditionResult(
                "statemachine_schema", False,
                "transition manifest unreadable (%s): %s"
                % (self.schema_file, exc))
        transitions = manifest.get("transitions", {})
        missing = [t for t in self.required_transitions if t not in transitions]
        if missing:
            return ConditionResult(
                "statemachine_schema", False,
                "missing transitions: %s" % ", ".join(missing))
        terminal = manifest.get("terminal_states", [])
        if "SOL_ADJUDICATE" in terminal:
            return ConditionResult(
                "statemachine_schema", False,
                "SOL_ADJUDICATE still terminal 鈥?v2 requires it routable "
                "(design 搂2.3.4)")
        return ConditionResult(
            "statemachine_schema", True,
            "all %d required transitions declared" % len(self.required_transitions))

    def check_rollback_key(self) -> ConditionResult:
        """Condition 6: a one-key rollback path exists."""
        rollback = str(self.policy.get("routing", {}).get(
            "rollback_mode", "")).strip()
        if rollback != "cold_start":
            return ConditionResult(
                "rollback_key", False,
                "routing.rollback_mode must be 'cold_start' (got %r) 鈥?the "
                "single-key rollback is mandatory" % rollback)
        return ConditionResult("rollback_key", True,
                               "rollback_mode=cold_start available")

    def check_default_adapter(self) -> ConditionResult:
        """The stable v1 entry points must route by policy, not by launcher."""
        required = {
            self.root / "harness" / "dispatch_v2.py":
                ("import dispatch as dispatch_v1", "orchestration_v2_adapter"),
            self.root / "harness" / "trigger_eval.py":
                ("trigger_eval_v2", "routing_mode"),
            self.root / "harness" / "statemachine.py":
                ("statemachine_v2", "routing_mode"),
            self.root / "hooks" / "sol_tool_gate_router.py":
                ("cold_start", "shadow", "layered"),
        }
        missing: list[str] = []
        for path, markers in required.items():
            try:
                text = path.read_text(encoding="utf-8")
            except OSError:
                missing.append(str(path))
                continue
            if not all(marker in text for marker in markers):
                missing.append(path.name + ":markers")
        if missing:
            marker_path = (self.root / "data" / "governor" /
                           "default_adapter.json")
            try:
                marker = json.loads(marker_path.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                marker = {}
            if marker.get("status") == "PASS":
                return ConditionResult("default_adapter", True,
                                       "adapter attestation marker PASS")
            return ConditionResult("default_adapter", False,
                                   "missing production adapter: %s" %
                                   ", ".join(missing))
        return ConditionResult("default_adapter", True,
                               "stable v1 entries route to v2 by one mode key")

    def check_meter_v2_fresh(self) -> ConditionResult:
        path = self.root / "data" / "usage" / "model_token_share_v2.json"
        try:
            report = json.loads(path.read_text(encoding="utf-8"))
            generated = float(report.get("generated_at",
                                         report.get("generated_ts", 0)))
            primary_name = str(report.get("primary_window", "rolling_5h"))
            primary = report["windows"][primary_name]
            status = str(primary["status"])
            denominator = int(primary["production_effective_tokens"])
            minimum = int(self.policy.get("tokens", {}).get(
                "minimum_denominator", 2_000_000))
            stale_after = float(self.policy.get("tokens", {}).get(
                "stale_after_s", 7200))
        except (OSError, ValueError, KeyError, TypeError) as exc:
            return ConditionResult("meter_v2_fresh", False,
                                   "v2 meter unreadable: %s" % exc)
        age = self._clock() - generated
        if age > stale_after:
            return ConditionResult("meter_v2_fresh", False,
                                   "v2 meter stale %.0fs > %.0fs" %
                                   (age, stale_after))
        if status != "OK" or denominator < minimum:
            return ConditionResult("meter_v2_fresh", False,
                                   "primary meter %s denominator=%d minimum=%d" %
                                   (status, denominator, minimum))
        return ConditionResult("meter_v2_fresh", True,
                               "fresh %.0fs denominator=%d" % (age, denominator))

    def check_plan_pipeline(self) -> ConditionResult:
        pipeline = self.root / "harness" / "orchestration" / "plan_pipeline.py"
        role_path = self.root / "agents" / "plan_expander.toml"
        try:
            source = pipeline.read_text(encoding="utf-8")
            with role_path.open("rb") as handle:
                role = tomllib.load(handle)
            policy_model = str(self.policy.get("models", {}).get("k3_model", ""))
        except (OSError, tomllib.TOMLDecodeError) as exc:
            marker_path = (self.root / "data" / "governor" /
                           "plan_pipeline.json")
            try:
                marker = json.loads(marker_path.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                marker = {}
            if (marker.get("status") == "PASS" and marker.get("model") ==
                    self.policy.get("models", {}).get("k3_model")):
                return ConditionResult("plan_pipeline", True,
                                       "plan pipeline attestation marker PASS")
            return ConditionResult("plan_pipeline", False,
                                   "plan pipeline unreadable: %s" % exc)
        if role.get("model") != policy_model:
            return ConditionResult("plan_pipeline", False,
                                   "plan_expander model diverges from policy")
        if "lifecycle_supervisor.py" not in source or "load_plan_settings" not in source:
            return ConditionResult("plan_pipeline", False,
                                   "plan pipeline bypasses config/lifecycle")
        return ConditionResult("plan_pipeline", True,
                               "config-sourced K3 through lifecycle supervisor")

    def check_provider_health(self) -> ConditionResult:
        expected_model = str(self.policy.get("models", {}).get("k3_model", ""))
        try:
            from provider_health import health_path
            path = health_path(self.root, expected_model)
        except (ImportError, ValueError) as exc:
            return ConditionResult("provider_health", False,
                                   "provider-health route invalid: %s" % exc)
        try:
            health = json.loads(path.read_text(encoding="utf-8"))
            status = str(health["status"])
            backoff = float(health.get("backoff_until", 0))
            age = self._clock() - float(health["ts"])
        except (OSError, ValueError, KeyError, TypeError) as exc:
            return ConditionResult("provider_health", False,
                                   "K3 health missing: %s" % exc)
        if (status != "healthy" or backoff > self._clock() or age > 3600
                or health.get("model") != expected_model):
            return ConditionResult("provider_health", False,
                                   "K3 status=%s age=%.0fs backoff_until=%.0f" %
                                   (status, age, backoff))
        return ConditionResult("provider_health", True,
                               "K3 provider healthy %.0fs ago" % age)

    def check_lifecycle_roster(self) -> ConditionResult:
        path = self.root / "data" / "lifecycle" / "exec_roster.json"
        try:
            roster = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            return ConditionResult("lifecycle_roster", False,
                                   "exec roster unreadable: %s" % exc)
        if not isinstance(roster.get("jobs"), dict):
            return ConditionResult("lifecycle_roster", False,
                                   "exec roster has no jobs map")
        return ConditionResult("lifecycle_roster", True,
                               "lifecycle roster present (%d jobs)" %
                               len(roster["jobs"]))

    def check_rollback_rehearsal(self) -> ConditionResult:
        marker_path = self.root / "data" / "governor" / "rollback_rehearsal.json"
        policy_path = self.root / "config" / "orchestration_policy_v2.toml"
        try:
            marker = json.loads(marker_path.read_text(encoding="utf-8"))
            current_hash = hashlib.sha256(policy_path.read_bytes()).hexdigest()
            age = self._clock() - float(marker["ts"])
        except (OSError, ValueError, KeyError, TypeError) as exc:
            return ConditionResult("rollback_rehearsal", False,
                                   "rollback rehearsal missing: %s" % exc)
        if marker.get("status") != "PASS" or age > 86400:
            return ConditionResult("rollback_rehearsal", False,
                                   "rollback rehearsal stale or failed")
        if marker.get("restored_sha256") != current_hash:
            return ConditionResult("rollback_rehearsal", False,
                                   "policy changed since rollback rehearsal")
        return ConditionResult("rollback_rehearsal", True,
                               "exact-byte rollback rehearsed %.0fs ago" % age)

    def check_dual_plane_hash(self) -> ConditionResult:
        path = self.root / "data" / "governor" / "dual_plane_hash.json"
        try:
            marker = json.loads(path.read_text(encoding="utf-8"))
            age = self._clock() - float(marker["ts"])
            policy_hash = hashlib.sha256((self.root / "config" /
                "orchestration_policy_v2.toml").read_bytes()).hexdigest()
        except (OSError, ValueError, KeyError, TypeError) as exc:
            return ConditionResult("dual_plane_hash", False,
                                   "dual-plane marker missing: %s" % exc)
        if (marker.get("status") != "PASS" or
                marker.get("windows_manifest_sha256") !=
                marker.get("wsl_manifest_sha256")):
            return ConditionResult("dual_plane_hash", False,
                                   "Windows/WSL managed manifests diverge")
        if age > 3600 or marker.get("policy_sha256") != policy_hash:
            return ConditionResult("dual_plane_hash", False,
                                   "dual-plane marker stale after managed change")
        return ConditionResult("dual_plane_hash", True,
                               "Windows/WSL managed manifest hashes agree")

    # -- the gate ----------------------------------------------------------------

    def check_all(self) -> GateResult:
        """Run every condition; log each result; never short-circuit.

        All conditions run even after a failure so the log names *every*
        broken precondition in one pass (actionable remediation).
        """
        guard = self.policy.get("gate_guard", {})
        checks: list[tuple[str, Callable[[], ConditionResult]]] = [
            ("require_consumer_heartbeat", self.check_consumer_heartbeat),
            ("require_exactly_once_canary", self.check_exactly_once_canary),
            ("require_k3_model_pinned", self.check_k3_model_pinned),
            ("require_validator_enabled", self.check_validator_enabled),
            ("require_statemachine_schema", self.check_statemachine_schema),
            ("require_rollback_key", self.check_rollback_key),
            ("require_default_adapter", self.check_default_adapter),
            ("require_meter_v2_fresh", self.check_meter_v2_fresh),
            ("require_plan_pipeline", self.check_plan_pipeline),
            ("require_provider_health", self.check_provider_health),
            ("require_lifecycle_roster", self.check_lifecycle_roster),
            ("require_rollback_rehearsal", self.check_rollback_rehearsal),
            ("require_dual_plane_hash", self.check_dual_plane_hash),
        ]
        results: list[ConditionResult] = []
        for policy_key, fn in checks:
            if not bool(guard.get(policy_key, True)):
                results.append(ConditionResult(
                    fn.__name__.removeprefix("check_"), True,
                    "SKIPPED by policy %s=false (logged)" % policy_key))
                continue
            results.append(fn())
        failed = tuple(r.name for r in results if not r.ok)
        gate = GateResult(allow=not failed, conditions=tuple(results),
                          failed=failed)
        self._log(gate)
        return gate

    def enable(self) -> GateResult:
        """Attempt the cold_start 鈫?layered flip.

        Runs :meth:`check_all`; on full pass, records the authorization
        (``layered_mode_authorized``). This method never edits the policy
        file itself 鈥?the operator applies the one-line change; the smoke
        gate re-runs this check and REFUSES a layered config whose gate log
        lacks a fresh authorization (config-lint form of 搂2.1 AC4).
        """
        gate = self.check_all()
        if gate.allow:
            policy_path = self.root / "config" / "orchestration_policy_v2.toml"
            set_mode(policy_path, "layered")
            bound_hash = policy_sha256(policy_path)
            atomic_write_json(self.root / "data" / "governor" /
                              "layered_authorization.json", {
                "schema": "codex-loop-layered-authorization/v2",
                "status": "PASS", "ts": self._clock(),
                "authorized_mode": "layered",
                "policy_sha256": bound_hash,
                "conditions": [c.to_dict() for c in gate.conditions],
            })
            self._log_raw({"event": "layered_mode_authorized",
                           "policy_sha256": bound_hash,
                           "conditions": [c.to_dict() for c in gate.conditions]})
            LOG.info("layered mode AUTHORIZED 鈥?all %d conditions green",
                     len(gate.conditions))
        else:
            self._log_raw({"event": "layered_mode_refused",
                           "failed": list(gate.failed)})
            LOG.error("layered mode REFUSED 鈥?failing conditions: %s",
                      ", ".join(gate.failed))
        return gate

    # -- logging -------------------------------------------------------------------

    def _log(self, gate: GateResult) -> None:
        self._log_raw({"event": "gate_check", **gate.to_dict()})

    def _log_raw(self, obj: dict[str, Any]) -> None:
        try:
            self.log_path.parent.mkdir(parents=True, exist_ok=True)
            with open(self.log_path, "a", encoding="utf-8") as fh:
                fh.write(json.dumps({"ts": self._clock(), **obj},
                                    sort_keys=True) + "\n")
        except OSError as exc:
            LOG.error("gate log write failed: %s", exc)


def _main(argv: Sequence[str]) -> int:
    """CLI: ``layered_gate.py check|enable [--root R]``.

    Exit 0 = all conditions green; 1 = refused (failures listed on stderr).
    """
    import argparse

    ap = argparse.ArgumentParser(description="layered-mode mechanical gate")
    ap.add_argument("command", choices=["check", "enable"])
    ap.add_argument("--root", default=os.environ.get("LOOP_ROOT", "."))
    ap.add_argument("--policy", default=None)
    args = ap.parse_args(argv)

    policy = load_policy(Path(args.policy)) if args.policy else None
    gate = LayeredGate(args.root, policy=policy)
    result = gate.enable() if args.command == "enable" else gate.check_all()
    print(json.dumps(result.to_dict(), indent=1))
    if not result.allow:
        for name in result.failed:
            print("FAILED: %s" % name, file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    sys.exit(_main(sys.argv[1:]))

#!/usr/bin/env python3
"""Launch a visible, lifecycle-supervised headless Codex wave.

This is the low-friction transport used when Desktop should remain a light
control plane.  It does not claim a birth from ``Popen`` alone: every task is
counted only after ``lifecycle_supervisor.py`` has published the matching
run-id as ``starting`` or ``running`` in ``exec_roster.json``.  The 8765
dashboard merges that roster with its WSL peer.

The input manifest is a JSON object with ``tasks``.  Each task needs
``task_id``, ``task_name``, ``prompt`` and ``cwd``; ``role`` defaults to
``worker``.  Concurrent workspace writes require explicitly distinct working
directories and ``allow_write=true``.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import time
import urllib.request
import uuid
from pathlib import Path
from typing import Any

try:
    from dispatch_v2 import (DispatcherV2, ExecutionPlane, ipybox_enabled_for,
                             resolve_role_pin)
    from lifecycle_supervisor import Store
    from orchestration_common import LoopPaths, OrchestrationPolicy, read_json
except ImportError:  # pragma: no cover
    sys.path.insert(0, str(Path(__file__).resolve().parent))
    from dispatch_v2 import (DispatcherV2, ExecutionPlane, ipybox_enabled_for,
                             resolve_role_pin)
    from lifecycle_supervisor import Store
    from orchestration_common import LoopPaths, OrchestrationPolicy, read_json


TASK_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,95}\Z")
ACTIVE = {"starting", "running"}
TERMINAL = {"completed", "failed", "timed_out", "cancelled", "spawn_failed", "lost"}
ROLE_SET = {"worker", "verifier", "reviewer", "plan_expander", "duty_officer"}


class WaveError(RuntimeError):
    pass


def load_manifest(path: Path) -> list[dict[str, Any]]:
    try:
        doc = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise WaveError(f"manifest unreadable: {exc}") from exc
    tasks = doc.get("tasks") if isinstance(doc, dict) else None
    if not isinstance(tasks, list) or not tasks:
        raise WaveError("manifest.tasks must be a non-empty list")
    seen: set[str] = set()
    write_cwds: set[str] = set()
    for index, task in enumerate(tasks):
        if not isinstance(task, dict):
            raise WaveError(f"task {index} is not an object")
        task_id = str(task.get("task_id") or "")
        if not TASK_ID.fullmatch(task_id) or task_id in seen:
            raise WaveError(f"invalid or duplicate task_id {task_id!r}")
        seen.add(task_id)
        packet_id = task.get("packet_id")
        if packet_id is not None:
            if not isinstance(packet_id, str) or not TASK_ID.fullmatch(packet_id):
                raise WaveError(f"task {task_id}: invalid packet_id")
            required = ("task_name",)
        else:
            required = ("task_name", "prompt", "cwd")
        for key in required:
            if not isinstance(task.get(key), str) or not task[key].strip():
                raise WaveError(f"task {task_id}: missing {key}")
        role = str(task.get("role") or "worker")
        if role not in ROLE_SET:
            raise WaveError(f"task {task_id}: unsupported role {role!r}")
        sandbox = str(task.get("sandbox") or "read-only")
        if sandbox not in {"read-only", "workspace-write"}:
            raise WaveError(f"task {task_id}: unsupported sandbox {sandbox!r}")
        if packet_id is not None and any(
                key in task for key in ("prompt", "cwd", "sandbox", "allow_write")):
            raise WaveError(f"task {task_id}: packet tasks may not override execution details")
        if sandbox == "workspace-write":
            if task.get("allow_write") is not True:
                raise WaveError(f"task {task_id}: workspace-write needs allow_write=true")
            cwd = str(Path(task["cwd"]).resolve()).casefold()
            if cwd in write_cwds:
                raise WaveError("workspace-write tasks must use distinct cwd values")
            write_cwds.add(cwd)
    return tasks


def roster_item(data_dir: Path, packet_id: str) -> dict[str, Any]:
    doc = read_json(data_dir / "lifecycle" / "exec_roster.json", {}) or {}
    row = (doc.get("jobs") or {}).get(packet_id)
    return row if isinstance(row, dict) else {}


def process_start_token(pid: Any) -> int | None:
    try:
        pid = int(pid)
    except (TypeError, ValueError):
        return None
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes
        handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, pid)
        if not handle:
            return None
        try:
            code = wintypes.DWORD()
            if (not ctypes.windll.kernel32.GetExitCodeProcess(
                    handle, ctypes.byref(code)) or code.value != 259):
                return None
            creation = wintypes.FILETIME(); exit_time = wintypes.FILETIME()
            kernel = wintypes.FILETIME(); user = wintypes.FILETIME()
            if not ctypes.windll.kernel32.GetProcessTimes(
                    handle, ctypes.byref(creation), ctypes.byref(exit_time),
                    ctypes.byref(kernel), ctypes.byref(user)):
                return None
            return ((int(creation.dwHighDateTime) << 32)
                    | int(creation.dwLowDateTime))
        finally:
            ctypes.windll.kernel32.CloseHandle(handle)
    try:
        return int(Path("/proc/%d/stat" % pid).read_text(
            encoding="ascii").split()[21])
    except (OSError, ValueError, IndexError):
        return None


def process_alive(pid: Any, expected_start: Any = None) -> bool:
    actual = process_start_token(pid)
    if actual is None:
        return False
    if expected_start is None:
        return True
    try:
        return actual == int(expected_start)
    except (TypeError, ValueError):
        return False

def recover_live_supervisor(data_dir: Path, packet_id: str) -> dict[str, Any]:
    row = roster_item(data_dir, packet_id)
    published = row.get("published_report")
    if (row.get("state") == "lost" and row.get("exit_code") == 0
            and isinstance(published, str) and Path(published).is_file()):
        return Store(data_dir).update(
            packet_id, run_id=str(row.get("run_id") or ""),
            attempt=int(row.get("attempt", 0) or 0), state="completed",
            recovered_by="headless_wave_completed_report")
    if (row.get("state") not in ACTIVE and row.get("run_id")
            and process_alive(row.get("supervisor_pid"),
                              row.get("supervisor_proc_start_ticks"))
            and process_alive(row.get("os_pid"),
                              row.get("worker_proc_start_ticks"))):
        return Store(data_dir).update(
            packet_id, run_id=str(row["run_id"]),
            attempt=int(row.get("attempt", 0) or 0), state="running",
            heartbeat_at=time.time(), recovered_by="headless_wave")
    return row


def observed(data_dir: Path, packet_id: str, run_id: str) -> bool:
    row = roster_item(data_dir, packet_id)
    # Only RUNNING is effective concurrency.  ``starting`` merely reserves an
    # initializing slot and may be followed by spawn_failed milliseconds later.
    return row.get("run_id") == run_id and row.get("state") == "running"


def wait_observed(data_dir: Path, packet_id: str, run_id: str,
                  timeout: float = 5.0, stable_for: float = 0.25) -> bool:
    deadline = time.monotonic() + timeout
    first_running: float | None = None
    while time.monotonic() < deadline:
        row = roster_item(data_dir, packet_id)
        if row.get("run_id") != run_id:
            first_running = None
        elif row.get("state") == "running":
            first_running = first_running or time.monotonic()
            if time.monotonic() - first_running >= stable_for:
                return True
        else:
            first_running = None
            if row.get("state") in {"completed", "failed", "timed_out", "cancelled",
                                    "spawn_failed"}:
                return False
        time.sleep(0.05)
    return False


def wait_generation_change(data_dir: Path, packet_id: str, prior_run_id: str,
                           timeout: float = 5.0) -> dict[str, Any]:
    """Wait until the packet-keyed roster is overwritten by the new birth."""
    deadline = time.monotonic() + timeout
    latest: dict[str, Any] = {}
    while time.monotonic() < deadline:
        latest = roster_item(data_dir, packet_id)
        run_id = str(latest.get("run_id") or "")
        if run_id and run_id != prior_run_id:
            return latest
        time.sleep(0.05)
    return latest


def _completion_fields(row: dict[str, Any]) -> dict[str, Any]:
    """Project terminal lifecycle data into a bounded parent-facing result.

    The full report remains on disk.  Returning only its path and a bounded
    first line preserves the Fable return convention without injecting a
    completed wave's full context into the parent Desktop turn.
    """
    report = row.get("published_report") or row.get("report")
    result: dict[str, Any] = {}
    if isinstance(report, str) and report:
        result["report_path"] = report
        try:
            text = Path(report).read_text(encoding="utf-8", errors="replace")
            lines = [line.strip() for line in text.splitlines() if line.strip()]
            if lines:
                result["summary"] = lines[0][:500]
        except OSError:
            pass
    if row.get("failure") is not None:
        result["failure"] = row.get("failure")
    return result


def wait_for_terminal(data_dir: Path, results: list[dict[str, Any]],
                      timeout: float) -> None:
    """Block the parent wave until its observed generations are terminal.

    This is deliberately a deterministic supervisor wait, not an LLM/Sol
    polling round.  Parent-bound waves use it by default so the calling
    Desktop turn remains open long enough to receive child reports.  A caller
    that intentionally wants detached background work must pass ``--detach``.
    """
    pending = {
        index for index, result in enumerate(results)
        if result.get("status") in {"running", "already_active"}
        and result.get("packet_id") and result.get("run_id")
    }
    if not pending:
        return
    deadline = time.monotonic() + max(0.0, float(timeout))
    while pending:
        progressed = False
        for index in tuple(pending):
            result = results[index]
            row = recover_live_supervisor(data_dir, str(result["packet_id"]))
            expected_run = result.get("run_id")
            evidence = row if row.get("run_id") == expected_run else {}
            if not evidence:
                # A newer generation may already own the packet-keyed live
                # row.  Terminal history is keyed by immutable run_id and is
                # therefore the authoritative ABA-safe completion source.
                for history_row in reversed(row.get("history") or []):
                    if (isinstance(history_row, dict)
                            and history_row.get("run_id") == expected_run
                            and history_row.get("state") in TERMINAL):
                        evidence = history_row
                        break
            state = str(evidence.get("state") or "")
            if state not in TERMINAL:
                continue
            result["status"] = state
            result.update(_completion_fields(evidence))
            pending.remove(index)
            progressed = True
        if not pending:
            return
        if time.monotonic() >= deadline:
            for index in pending:
                results[index]["status"] = "wait_timeout"
                results[index]["failure"] = {
                    "reason": "parent_wave_wait_timeout",
                    "timeout_seconds": timeout,
                }
            return
        if not progressed:
            time.sleep(0.20)


def resolve_codex_binary() -> str:
    explicit = os.environ.get("CODEX_HEADLESS_BIN")
    if explicit:
        path = Path(explicit).resolve()
        if path.is_file():
            return str(path)
        raise WaveError(f"CODEX_HEADLESS_BIN is not a file: {path}")
    if os.name == "nt":
        npm_vendor = (Path.home() / "AppData" / "Roaming" / "npm" / "node_modules"
                      / "@openai" / "codex" / "node_modules" / "@openai"
                      / "codex-win32-x64" / "vendor" / "x86_64-pc-windows-msvc"
                      / "bin" / "codex.exe")
        if npm_vendor.is_file():
            return str(npm_vendor)
        candidate = shutil.which("codex.exe")
    else:
        candidate = shutil.which("codex")
    if not candidate:
        raise WaveError("headless codex executable not found")
    return candidate


def opencodex_healthy() -> bool:
    try:
        with urllib.request.urlopen("http://127.0.0.1:10100/healthz", timeout=2.0) as response:
            value = json.loads(response.read(65536).decode("utf-8"))
        return response.status == 200 and value.get("status") == "ok"
    except Exception:
        return False


def provider_birth_allowed(root: Path, model: str) -> bool:
    from provider_health import backoff_active
    blocked, _ = backoff_active(root, model)
    return not blocked


def launch_supervisor(command: list[str], root: Path, log_path: Path) -> int:
    log_path.parent.mkdir(parents=True, exist_ok=True)
    log = log_path.open("ab")
    kwargs: dict[str, Any] = {
        "cwd": str(root), "stdin": subprocess.DEVNULL,
        "stdout": log, "stderr": subprocess.STDOUT, "close_fds": True,
    }
    if os.name == "nt":
        kwargs["creationflags"] = (getattr(subprocess, "CREATE_NO_WINDOW", 0)
                                   | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0))
    else:
        kwargs["start_new_session"] = True
    try:
        proc = subprocess.Popen(command, **kwargs)
        return proc.pid
    finally:
        log.close()


def task_key(manifest: Path, task_id: str) -> str:
    digest = hashlib.sha256(str(manifest.resolve()).encode("utf-8")).hexdigest()[:10]
    return f"adhoc-{digest}-{task_id}"[:96]

#!/usr/bin/env python3
"""Fail closed when a LOOP root attempts an ambiguous child birth.

The configured default child model is defence in depth, not authorization.
Every ordinary Desktop child must be born with an explicit LOOP role, Sonnet
4.6 model, ultra effort, and an independent context.
"""
from __future__ import annotations

import json
import os
import sys
from pathlib import Path
from typing import Any

from leaf_agent_spawn_gate import is_spawn_tool, session_is_child


APPROVED_MODEL = "weiwu/aws.claude-sonnet-4.6"
APPROVED_EFFORT = "ultra"
APPROVED_ROLES = frozenset({
    "worker", "verifier", "reviewer", "plan_expander", "duty_officer",
})


def deny(reason: str) -> dict[str, Any]:
    return {"hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": "deny",
        "permissionDecisionReason": "LOOP root spawn denied: " + reason,
    }}


def decision(payload: dict[str, Any], sessions: Path) -> dict[str, Any] | None:
    tool_name = str(payload.get("tool_name") or payload.get("tool") or payload.get("name") or "")
    if not is_spawn_tool(tool_name) or "spawn_agent" not in tool_name.casefold():
        return None
    session_id = payload.get("session_id") or payload.get("thread_id")
    if os.environ.get("LOOP_LEAF_AGENT", "").strip() == "1" or session_is_child(session_id, sessions):
        # The dedicated leaf gate owns this case and denies all descendants.
        return None
    arguments = payload.get("tool_input")
    if not isinstance(arguments, dict):
        return deny("tool_input is absent or malformed; ambiguous births fail closed")

    role = str(arguments.get("agent_type") or "").strip().casefold()
    if not role or role == "default":
        return deny("agent_type must be an explicit LOOP role; roleless/default is prohibited")
    if role not in APPROVED_ROLES:
        return deny(f"agent_type={role!r} is not an approved LOOP child role")

    model = str(arguments.get("model") or "").strip()
    if model != APPROVED_MODEL:
        return deny(f"model must be explicitly pinned to {APPROVED_MODEL}")

    effort = str(arguments.get("reasoning_effort") or "").strip().casefold()
    if effort != APPROVED_EFFORT:
        return deny(f"reasoning_effort must be explicitly pinned to {APPROVED_EFFORT}")

    if arguments.get("fork_context") is True:
        return deny("fork_context=true is prohibited; LOOP children use independent context")
    return None


def main() -> int:
    try:
        payload = json.loads(sys.stdin.read() or "{}")
    except ValueError:
        payload = {}
    sessions = Path(os.environ.get(
        "CODEX_SESSIONS_DIR",
        str(Path(os.environ.get("CODEX_HOME", str(Path.home() / ".codex"))) / "sessions"),
    )).resolve()
    result = decision(payload if isinstance(payload, dict) else {}, sessions)
    if result is not None:
        print(json.dumps(result, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Deny recursive subagent births while leaving root-agent dispatch untouched.

The global throughput agreement authorizes roots to fill the shared LOOP
capacity.  A worker/verifier/reviewer is a leaf: allowing every leaf to apply
the same agreement recursively creates a 16x16 birth cascade.  This hook uses
the immutable rollout session_meta parent_thread_id as the authority.  It
does not cap root concurrency and does not terminate existing work.
"""
from __future__ import annotations

import json
import os
import sys
from pathlib import Path
from typing import Any


SPAWN_NAMES = ("spawn_agent", "create_thread", "fork_thread")


def is_spawn_tool(name: Any) -> bool:
    value = str(name or "").casefold()
    return any(item in value for item in SPAWN_NAMES)


def session_is_child(session_id: Any, sessions: Path) -> bool:
    value = str(session_id or "").strip()
    if not value or not sessions.exists():
        return False
    matches = sorted(sessions.rglob("rollout-*%s*.jsonl" % value),
                     key=lambda path: path.stat().st_mtime, reverse=True)
    for path in matches:
        try:
            with path.open(encoding="utf-8", errors="replace") as handle:
                for line in handle:
                    try:
                        row = json.loads(line)
                    except ValueError:
                        continue
                    if row.get("type") != "session_meta":
                        continue
                    payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
                    parent = payload.get("parent_thread_id")
                    if not parent:
                        source = payload.get("source") if isinstance(payload.get("source"), dict) else {}
                        subagent = source.get("subagent") if isinstance(source.get("subagent"), dict) else {}
                        spawn = subagent.get("thread_spawn") if isinstance(subagent.get("thread_spawn"), dict) else {}
                        parent = spawn.get("parent_thread_id") or spawn.get("parent_session_id")
                    return bool(parent)
        except OSError:
            continue
    return False


def decision(payload: dict[str, Any], sessions: Path) -> dict[str, Any] | None:
    if not is_spawn_tool(payload.get("tool_name") or payload.get("tool") or payload.get("name")):
        return None
    session_id = payload.get("session_id") or payload.get("thread_id")
    marked_leaf = os.environ.get("LOOP_LEAF_AGENT", "").strip() == "1"
    if not marked_leaf and not session_is_child(session_id, sessions):
        return None
    return {"hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": "deny",
        "permissionDecisionReason": (
            "LOOP leaf agents cannot recursively spawn agents. Return the bounded "
            "result to the root orchestrator; the root owns shared global-60 refill."
        ),
    }}


def main() -> int:
    try:
        payload = json.loads(sys.stdin.read() or "{}")
    except ValueError:
        payload = {}
    sessions = Path(os.environ.get(
        "CODEX_SESSIONS_DIR",
        str(Path(os.environ.get("CODEX_HOME", str(Path.home() / ".codex"))) / "sessions"),
    )).resolve()
    result = decision(payload if isinstance(payload, dict) else {}, sessions)
    if result is not None:
        print(json.dumps(result, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

